import {
	Component,
	Element,
	Event,
	EventEmitter,
	Host,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { hasSlot } from "../../utils/slot";

import { parseDuration } from "../../utils/animate";

// TODO: animations
// import { animateTo, parseDuration, stopAnimations } from '../../utils/animate';
// import { getAnimation } from '../../utils/animate.js';

/**
 * @since 1.0.29
 * @status stable
 *
 * @slot - The tooltip's target element. Avoid slotting in more than one element, as subsequent ones will be ignored.
 * @slot content - The content to render in the tooltip. Alternatively, you can use the `content` attribute.
 *
 * @part base - The component's base wrapper, an `<hbr-popup>` element.
 * @part base__popup - The popup's exported `popup` part. Use this to target the tooltip's popup container.
 * @part base__arrow - The popup's exported `arrow` part. Use this to target the tooltip's arrow.
 * @part body - The tooltip's body where its content is rendered.
 *
 * @animation tooltip.show - The animation to use when showing the tooltip.
 * @animation tooltip.hide - The animation to use when hiding the tooltip.
 */

@Component({
	tag: "hbr-tooltip",
	styleUrl: "tooltip.scss",
	shadow: true,
})
export class HbrTooltip {
	private hoverTimeout: number;

	private popupRef: HTMLHbrPopupElement;
	private popupContentRef: HTMLDivElement;
	private anchorRef: HTMLElement; //<div slot="anchor">
	private slottedAnchorRef: HTMLElement; //actual slotted element like <hbr-button>
	private dismissedOnClick = false;
	private cancelHide = false;
	private originalAnchorTooltip = "";
	private hadAnchorTooltip = false;
	private tooltipAnchorRef: (HTMLElement & { tooltip?: string }) | undefined;
	private describedIconAnchorRef: HTMLElement | undefined;
	private originalDescribedIconAttrs = new Map<string, string | null>();

	@Element() host!: HTMLHbrTooltipElement;

	@State() hasContent = false;
	@State() hasAnchorSlot = false;

	/**
	 * The element the popup will be anchored to. If the anchor lives outside of the popup, you can provide its `id` or a
	 * reference to it here. If the anchor lives inside the popup, the default
	 * @deprecated Use `enable-popover` instead to avoid external anchors and portal usage.
	 */
	@Prop() anchor: HTMLElement | string;

	/** The tooltip's content. If you need to display HTML, use the `content` slot instead. */
	@Prop() content = "";

	/**
	 * The preferred placement of the tooltip. Note that the actual placement may vary as needed to keep the tooltip
	 * inside of the viewport.
	 */
	@Prop() placement:
		| "top"
		| "top-start"
		| "top-end"
		| "right"
		| "right-start"
		| "right-end"
		| "bottom"
		| "bottom-start"
		| "bottom-end"
		| "left"
		| "left-start"
		| "left-end" = "top";

	/** Disables the tooltip so it won't show when triggered. */
	@Prop({ reflect: true }) disabled = false;

	/** The distance in pixels from which to offset the tooltip away from its target. */
	@Prop() distance = 8;

	/** Indicates whether or not the tooltip is open. You can use this in lieu of the show/hide methods. */
	@Prop({ mutable: true, reflect: true }) open = false;

	/** The distance in pixels from which to offset the tooltip along its target. */
	@Prop() skidding = 0;

	/**
	 * Controls how the tooltip is activated. Possible options include `click`, `hover`, `focus`, and `manual`. Multiple
	 * options can be passed by separating them with a space. When manual is used, the tooltip must be activated
	 * programmatically.
	 */
	@Prop() trigger = "hover";

	/**
	 * Enable this option to prevent the tooltip from being clipped when the component is placed inside a container with
	 * `overflow: auto|hidden|scroll`. Hoisting uses a fixed positioning strategy that works in many, but not all,
	 * scenarios.
	 */
	@Prop({ reflect: true }) hoist = false;

	/** dismiss the tooltip when clicking on the trigger element, in terms of the "trigger = hover" */
	@Prop({ reflect: true }) dismissOnClick = false;

	/**
	 * sizes correspond to max-width of tooltip
	 */
	@Prop() size: "small" | "medium" | "large";

	/** Enable the native popover feature so that the tooltip layers above clipping containers. @version: 2.18.43 */
	@Prop() enablePopover = false;

	/** Emitted when the tooltip begins to show. */
	@Event({ eventName: "hbr-show" }) hbrShow: EventEmitter;

	/** Emitted after the tooltip has shown and all animations are complete. */
	@Event({ eventName: "hbr-after-show" }) hbrAfterShow: EventEmitter;

	/** Emitted when the tooltip begins to hide. */
	@Event({ eventName: "hbr-hide" }) hbrHide: EventEmitter;

	/** Emitted after the tooltip has hidden and all animations are complete. */
	@Event({ eventName: "hbr-after-hide" }) hbrAfterHide: EventEmitter;

	/** Emitted when body is clicked. Calling `event.preventDefault()` will prevent the tooltip from closing. */
	@Event({ eventName: "hbr-tooltip-dismiss" }) hbrTooltipDismiss: EventEmitter;

	// Use the owning document so tooltip listeners work when rendered inside an iframe, such as docs samples.
	private getDocument() {
		return this.host?.ownerDocument ?? document;
	}

	private getKeydownDocuments() {
		const ownerDocument = this.getDocument();
		const documents = [ownerDocument];

		try {
			const parentDocument = ownerDocument.defaultView?.parent?.document;
			if (parentDocument && parentDocument !== ownerDocument) {
				documents.push(parentDocument);
			}
		} catch {
			// Ignore cross-origin parent frames.
		}

		return documents;
	}

	private addKeydownListener() {
		for (const doc of this.getKeydownDocuments()) {
			doc.addEventListener("keydown", this.handleDocumentKeyDown);
		}
	}

	private removeKeydownListener() {
		for (const doc of this.getKeydownDocuments()) {
			doc.removeEventListener("keydown", this.handleDocumentKeyDown);
		}
	}

	@Watch("open")
	async handleOpenChange() {
		if (!this.popupRef) return;
		if (this.open) {
			if (this.disabled) {
				return;
			}

			// Show
			this.hbrShow.emit();

			// TODO: animation
			/**  await stopAnimations(this.popupContentRef); */
			if (this.popupContentRef) this.popupContentRef.hidden = false;
			this.popupRef.active = true;
			/**
			const { keyframes, options } = getAnimation(this.host, 'tooltip.show', { dir: "ltr" });
			await animateTo(this.popupRef.popupRef, keyframes, options);
			*/
			this.hbrAfterShow.emit();
			// Dismiss on click outside
			document.addEventListener("click", this.handleBodyClick);
			this.addKeydownListener();
		} else {
			// Hide
			this.hbrHide.emit();

			// TODO: animation
			/**
			await stopAnimations(this.popupContentRef);
			const { keyframes, options } = getAnimation(this, 'tooltip.hide', { dir: this.localize.dir() });
			await animateTo(this.popupRef.popupRef, keyframes, options);
			*/
			this.popupRef.active = false;
			if (this.popupContentRef) this.popupContentRef.hidden = true;

			this.hbrAfterHide.emit();
			// Remove Dismiss on click outside
			// TODO: remove event does not work in portal case, probably because handleBodyClick reference changes
			document.removeEventListener("click", this.handleBodyClick);
			this.removeKeydownListener();
		}
	}

	@Watch("content")
	@Watch("distance")
	@Watch("hoist")
	@Watch("placement")
	@Watch("skidding")
	async handleOptionsChange() {
		await this.popupRef?.reposition();
	}
	@Watch("content")
	handleContentChange() {
		this.syncAnchorDescription(true);
	}

	@Watch("disabled")
	handleDisabledChange() {
		if (this.disabled && this.open) {
			this.open = false;
		}
	}

	@Watch("anchor")
	handleAnchorChange() {
		if (this.anchor && typeof this.anchor === "string") {
			this.anchorRef = document.querySelector(this.anchor);
		} else if (this.anchor instanceof HTMLElement) {
			this.anchorRef = this.anchor;
		}

		if (this.anchorRef) {
			this.bindEventsToAnchor();
		}

		if (this.anchorRef) {
			const slot = this.anchorRef.querySelector("slot") as HTMLSlotElement;
			if (!slot) {
				if (this.anchorRef instanceof HTMLElement) {
					this.slottedAnchorRef = this.anchorRef;
				}
				this.syncAnchorDescription(true);
				return;
			}
			const slotted = slot?.assignedElements({
				flatten: true,
			})[0] as HTMLElement;

			if (slotted) {
				this.slottedAnchorRef = slotted;
			}
		}

		this.syncAnchorDescription(true);
	}

	/** Shows the tooltip. */
	@Method()
	async show() {
		if (this.open) {
			return undefined;
		}

		this.open = true;
	}

	/** Hides the tooltip */
	@Method()
	async hide() {
		if (this.cancelHide) {
			return;
		}
		if (!this.open) {
			return undefined;
		}

		this.open = false;
	}

	private handleBlur = () => {
		if (this.hasTrigger("focus")) {
			this.open = false;
		}
	};

	private handleClick = () => {
		if (this.hasTrigger("hover")) {
			if (this.dismissOnClick) {
				this.open = false;
				this.dismissedOnClick = true;
			}
		} else if (this.hasTrigger("click")) {
			this.open = !this.open;
		}
	};

	private handleFocus = () => {
		if (this.hasTrigger("focus")) {
			this.open = true;
		}
	};

	private handleKeyDown = (event: KeyboardEvent) => {
		// Pressing escape when the target element has focus should dismiss the tooltip
		if (this.open && event.key === "Tab") {
			event.stopPropagation();
			this.open = false;
		}

		if (event.key === "Enter" && this.hasTrigger("click")) {
			this.open = !this.open;
		}
	};

	private handleKeyUp = (event: KeyboardEvent) => {
		if (event.key === "Tab" && this.hasTrigger("hover")) {
			event.stopPropagation();
			this.open = true;
		}
	};

	private handleDocumentKeyDown = (event: KeyboardEvent) => {
		if (this.open && event.key === "Escape") {
			clearTimeout(this.hoverTimeout);
			this.open = false;
		}
	};

	private handleMouseOver = () => {
		if (this.hasTrigger("hover")) {
			const delay = parseDuration(
				getComputedStyle(this.host).getPropertyValue("--show-delay"),
			);
			clearTimeout(this.hoverTimeout);
			this.hoverTimeout = window.setTimeout(() => {
				if (this.dismissOnClick) {
					if (!this.dismissedOnClick) {
						this.show();
					}
				} else {
					this.show();
				}
			}, delay);
		}
	};

	private handleMouseLeave = () => {
		if (this.dismissOnClick) {
			this.dismissedOnClick = false;
		}
	};

	private handleMouseOut = () => {
		if (this.hasTrigger("hover")) {
			const delay = parseDuration(
				getComputedStyle(this.host).getPropertyValue("--hide-delay"),
			);
			clearTimeout(this.hoverTimeout);
			this.hoverTimeout = window.setTimeout(() => {
				this.hide();
			}, delay);
		}
	};

	private hasTrigger(triggerType: string) {
		const triggers = this.trigger.split(" ");
		return triggers.includes(triggerType);
	}

	private isTargetWithin(event: CustomEvent) {
		const target = event.target as HTMLElement;
		return (
			target.closest("hbr-tooltip") === this.host ||
			target.closest(".hbr-css-tooltip__anchor") === this.anchorRef ||
			event.target === this.anchorRef
		);
	}

	private handleBodyClick(event: CustomEvent) {
		if (this.isTargetWithin(event)) return;
		const hbrTooltipDismiss = this.hbrTooltipDismiss.emit();
		if (!hbrTooltipDismiss.defaultPrevented) {
			this.hide();
		}
	}

	private bindEventsToAnchor() {
		this.anchorRef.addEventListener("blur", this.handleBlur, true);
		this.anchorRef.addEventListener("focus", this.handleFocus, true);
		this.anchorRef.addEventListener("click", this.handleClick);
		this.anchorRef.addEventListener("keydown", this.handleKeyDown);
		this.anchorRef.addEventListener("keyup", this.handleKeyUp);
		this.anchorRef.addEventListener("mouseover", this.handleMouseOver);
		this.anchorRef.addEventListener("mouseout", this.handleMouseOut);
		this.anchorRef.addEventListener("mouseleave", this.handleMouseLeave);
	}

	private getAccessibleAnchor(): HTMLElement | null {
		const slotted = this.anchorRef
			?.querySelector("slot")
			?.assignedElements({ flatten: true })[0];
		if (slotted instanceof HTMLElement) {
			return slotted;
		}

		if (this.slottedAnchorRef instanceof HTMLElement) {
			return this.slottedAnchorRef;
		}
		if (this.anchorRef instanceof HTMLElement) {
			return this.anchorRef;
		}
		return null;
	}

	private getDefaultSlottedAnchor(): HTMLElement | null {
		if (!this.anchorRef?.classList.contains("hbr-css-tooltip__anchor")) {
			return null;
		}

		const slotted = this.anchorRef
			?.querySelector("slot")
			?.assignedElements({ flatten: true })[0];
		return slotted instanceof HTMLElement ? slotted : null;
	}

	private getTooltipText() {
		if (this.hasContent) {
			const contentSlot = this.host.querySelector("[slot='content']");
			return contentSlot?.textContent?.trim() || "";
		}
		return (this.content || "").trim();
	}

	private syncButtonTooltipProp(
		anchor: HTMLElement,
		shouldAttach: boolean,
		tooltipText: string,
	) {
		const buttonAnchor = anchor as HTMLElement & { tooltip?: string };
		const supportsTooltipProp =
			["hbr-button", "hbr-icon-button", "hbr-radio-button"].includes(
				anchor.localName,
			) && "tooltip" in buttonAnchor;

		if (this.tooltipAnchorRef && this.tooltipAnchorRef !== buttonAnchor) {
			this.restoreAnchorTooltip();
		}

		if (!supportsTooltipProp || !shouldAttach) {
			if (this.tooltipAnchorRef === buttonAnchor) {
				this.restoreAnchorTooltip();
			}
			return supportsTooltipProp;
		}

		if (!this.hadAnchorTooltip || this.tooltipAnchorRef !== buttonAnchor) {
			this.originalAnchorTooltip = buttonAnchor.tooltip || "";
			this.hadAnchorTooltip = true;
			this.tooltipAnchorRef = buttonAnchor;
		}

		if (buttonAnchor.tooltip !== tooltipText) {
			buttonAnchor.tooltip = tooltipText;
		}

		return true;
	}

	private syncIconAnchorDescription(
		shouldAttach: boolean,
		tooltipText: string,
	) {
		const iconAnchor = this.getDefaultSlottedAnchor();
		const shouldDescribe =
			iconAnchor?.localName === "hbr-icon" &&
			shouldAttach &&
			!!tooltipText &&
			this.hasTrigger("hover");

		if (
			this.describedIconAnchorRef &&
			this.describedIconAnchorRef !== iconAnchor
		) {
			this.restoreIconAnchorDescription();
		}

		if (!iconAnchor || !shouldDescribe) {
			if (!iconAnchor || this.describedIconAnchorRef === iconAnchor) {
				this.restoreIconAnchorDescription();
			}
			return;
		}

		if (this.describedIconAnchorRef !== iconAnchor) {
			this.describedIconAnchorRef = iconAnchor;
			this.originalDescribedIconAttrs.clear();
			for (const name of ["tabindex", "aria-description"]) {
				this.originalDescribedIconAttrs.set(
					name,
					iconAnchor.getAttribute(name),
				);
			}
		}

		if (!iconAnchor.hasAttribute("tabindex")) {
			iconAnchor.setAttribute("tabindex", "0");
		}
		iconAnchor.setAttribute("aria-description", tooltipText);
	}

	private syncAnchorDescription(shouldAttach: boolean) {
		const anchor = this.getAccessibleAnchor();
		if (!anchor) return;

		const tooltipText = this.getTooltipText();
		const shouldAttachWithText = shouldAttach && !!tooltipText;
		this.syncButtonTooltipProp(anchor, shouldAttachWithText, tooltipText);
		this.syncIconAnchorDescription(shouldAttachWithText, tooltipText);
	}

	private restoreAnchorTooltip() {
		if (!this.hadAnchorTooltip || !this.tooltipAnchorRef) return;

		this.tooltipAnchorRef.tooltip = this.originalAnchorTooltip;
		this.originalAnchorTooltip = "";
		this.hadAnchorTooltip = false;
		this.tooltipAnchorRef = undefined;
	}

	private restoreIconAnchorDescription() {
		if (!this.describedIconAnchorRef) return;

		for (const [name, value] of this.originalDescribedIconAttrs) {
			if (value === null) {
				this.describedIconAnchorRef.removeAttribute(name);
			} else {
				this.describedIconAnchorRef.setAttribute(name, value);
			}
		}

		this.describedIconAnchorRef = undefined;
		this.originalDescribedIconAttrs.clear();
	}

	private handleSlotChange() {
		this.hasContent = hasSlot(this.host, "content");
		this.syncAnchorDescription(true);
	}

	private handleAnchorSlotChange = () => {
		this.hasAnchorSlot = hasSlot(this.host);
		this.syncAnchorDescription(true);
	};

	handleArrowMouseLeave = () => {
		this.cancelHide = false;
		this.handleMouseOut();
	};

	handleArrowMouseEnter = () => {
		this.cancelHide = true;
	};

	connectedCallback() {
		this.handleBodyClick = this.handleBodyClick.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.hasAnchorSlot = hasSlot(this.host);
	}

	componentDidLoad() {
		this.handleAnchorChange();

		if (this.popupContentRef) this.popupContentRef.hidden = !this.open;
		// If the tooltip is visible on init, update its position
		if (this.open) {
			this.handleOpenChange();
			this.popupRef.active = true;
			this.popupRef?.reposition();
		}
	}

	disconnectedCallback() {
		document.removeEventListener("click", this.handleBodyClick);
		this.removeKeydownListener();
		this.restoreAnchorTooltip();
		this.restoreIconAnchorDescription();
	}

	render() {
		return (
			<Host>
				<hbr-popup
					part="base"
					ref={(el) => {
						this.popupRef = el;
					}}
					anchor={this.anchor}
					class={{
						tooltip: true,
						"tooltip--open": this.open,
						...(this.size ? { [`tooltip--${this.size}`]: true } : null),
					}}
					placement={this.placement}
					distance={this.distance}
					skidding={this.skidding}
					strategy={this.enablePopover || this.hoist ? "fixed" : "absolute"}
					enablePopover={this.enablePopover}
					flip
					shift
					arrow
					onHbr-arrow-mouseleave={this.handleArrowMouseLeave}
					onHbr-arrow-mouseenter={this.handleArrowMouseEnter}
				>
					{!this.anchor ? (
						<div
							slot="anchor"
							class={{
								"hbr-css-tooltip__anchor": true,
								"hbr-css-tooltip__anchor--empty": !this.hasAnchorSlot,
							}}
							ref={(el) => {
								this.anchorRef = el as HTMLDivElement;
							}}
						>
							<slot onSlotchange={this.handleAnchorSlotChange} />
						</div>
					) : null}
					<div
						part="body"
						class="tooltip__body"
						aria-hidden="true"
						onMouseLeave={() => {
							this.cancelHide = false;
							this.handleMouseOut();
						}}
						onMouseEnter={() => {
							this.cancelHide = true;
						}}
						ref={(el) => {
							this.popupContentRef = el as HTMLDivElement;
						}}
					>
						<slot name="content" onSlotchange={this.handleSlotChange}>
							{this.content}
						</slot>
					</div>
				</hbr-popup>
			</Host>
		);
	}
}
